function token(v){return String(v||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function skillMatches(required,studentSkill){const a=token(required),b=token(studentSkill);return a===b||a.includes(b)||b.includes(a)||Object.values(roleAliases).some(group=>group.includes(a)&&group.includes(b))}
function calculateCompatibility(student,project){
  const required=project.tags||[], ranked=required.map((skill,i)=>({skill,importance:i===0?'Essential':i===1?'Important':'Nice to have',weight:i===0?1.3:i===1?1.1:.85}));
  let skillPoints=0,skillMax=0,missing=[]; ranked.forEach(r=>{skillMax+=r.weight;const match=(student.skills||[]).find(s=>skillMatches(r.skill,s.name));if(match)skillPoints+=r.weight*(match.level/100);else missing.push(r.skill)});
  const skillScore=skillMax?skillPoints/skillMax*100:0; const interestMatch=(student.interests||[]).some(i=>token(i)===token(project.interest)||token(project.interest).includes(token(i))||token(i).includes(token(project.interest))); const interestScore=interestMatch?100:0;
  const roleMatch=(project.roles||[]).some(r=>token(student.role).includes(token(r))||token(r).includes(token(student.role))||skillMatches(r,student.role)); const roleScore=roleMatch?100:(student.role?55:0);
  const projectText=token(`${project.desc} ${project.title} ${(project.tags||[]).join(' ')}`); const availabilityMatch=token(student.availability).includes('flexible')||projectText.includes(token(student.availability).split(' ')[0]); const availabilityScore=availabilityMatch?100:65;
  const expText=token(`${student.bio||''} ${student.experience||''} ${(student.projects||[]).join(' ')}`); const expHits=required.filter(s=>expText.includes(token(s).split(' ')[0])).length; const experienceScore=required.length?Math.min(100,45+expHits/required.length*55):50;
  const breakdown={skills:Math.round(skillScore),interests:Math.round(interestScore),role:Math.round(roleScore),availability:Math.round(availabilityScore),experience:Math.round(experienceScore)};
  const score=Math.max(0,Math.min(100,Math.round(skillScore*.5+interestScore*.2+roleScore*.1+availabilityScore*.1+experienceScore*.1)));
  const reasons=[]; ranked.forEach(r=>{const m=(student.skills||[]).find(s=>skillMatches(r.skill,s.name));if(m&&m.level>=80)reasons.push({type:'good',text:`Strong ${r.skill} proficiency`});else if(m)reasons.push({type:'good',text:`${r.skill} experience to build on`})}); if(interestMatch)reasons.push({type:'good',text:`Shared ${project.interest} interest`}); if(availabilityMatch)reasons.push({type:'good',text:'Availability lines up'}); if(missing[0])reasons.push({type:'warn',text:`Limited ${missing[0]} experience`}); if(!interestMatch)reasons.push({type:'warn',text:'Different interest areas'}); return {score,breakdown,reasons:reasons.slice(0,5),missingSkills:missing};
}
function rankStudentsForProject(project,exclude=[]){return people.filter(p=>!exclude.includes(p.initials)).map(student=>({...student,match:calculateCompatibility(student,project)})).sort((a,b)=>b.match.score-a.match.score)}
function identifyTeamGaps(project,selectedPeople=[]){const covered=selectedPeople.flatMap(p=>(p.skills||[]).map(s=>token(s.name)));const required=(project.roles&&project.roles.length?project.roles:project.tags||[]).filter((role,i)=>i<4);const missing=required.filter(role=>!covered.some(skill=>skillMatches(role,skill)));return {missing,hasGap:missing.length>0}}
function teamMembers(project){const ids=teamStates[project.id]?.members||project.people||[];return ids.map((id,index)=>people.find(p=>p.initials===id)||(id===user.initials?user:{name:id==='AK'?'Aarav Kapoor':id==='JM'?'Jules Martin':id==='RS'?'Riya Shah':`Team member ${id}`,initials:id,role:project.roles?.[index]||'Project contributor',bio:'',skills:(project.tags||[]).slice(index,index+2).map(name=>({name,level:78})),interests:[project.interest],availability:'Flexible',projects:[],score:78,avatar:['mint','orange','blue','pink'][index%4]})).filter(Boolean)}
function saveTeam(project,members){teamStates[project.id]={members:members.map(p=>p.initials)};storage.write('teams',teamStates)}
function teamHealth(project,members){const required=project.tags||[],covered=required.filter(skill=>members.some(p=>(p.skills||[]).some(s=>skillMatches(skill,s.name)))).length;const roles=project.roles||required,roleCovered=roles.filter(role=>members.some(p=>skillMatches(role,p.role)||(p.skills||[]).some(s=>skillMatches(role,s.name)))).length;const interests=members.length?members.reduce((sum,p)=>sum+(p.interests||[]).filter(i=>i===project.interest||token(i).includes(token(project.interest))||token(project.interest).includes(token(i))).length,0)/members.length:0;const match=members.length?members.reduce((sum,p)=>sum+calculateCompatibility(p,project).score,0)/members.length:0;const skill=required.length?Math.round(covered/required.length*100):0,role=roles.length?Math.round(roleCovered/roles.length*100):0,interestScore=Math.min(100,Math.round(interest*100));return {skill,role,interest:interestScore,overall:Math.round(skill*.35+role*.25+interestScore*.15+match*.25)}}
function rankTeamCandidates(project,members){const gaps=identifyTeamGaps(project,members).missing;return rankStudentsForProject(project,members.map(p=>p.initials)).map(p=>{const fills=gaps.filter(g=>(p.skills||[]).some(s=>skillMatches(g,s.name))||skillMatches(g,p.role)).length;return {...p,teamFit:Math.min(100,p.match.score+fills*7),fills}}).sort((a,b)=>b.teamFit-a.teamFit)}
function teamsPage(){const activePeople=people.filter(p=>p.score>=87),pending=teamRequests.filter(r=>r.status==='Pending').length;return shell(`<div class="page"><section class="hero teams-hero"><div><div class="kicker">Your network</div><h1>Build with people.</h1><p>Keep track of your project circles, discover new collaborators and make the next introduction feel natural.</p></div><button class="button primary" onclick="location.hash='/discover'">Find new contacts</button></section><div class="team-overview-row"><div class="team-overview-card"><span class="stat-label">Active connections</span><strong>${activePeople.length+3}</strong><p>Across your project circles</p></div><div class="team-overview-card"><span class="stat-label">Project circles</span><strong>${projects.length>3?3:projects.length}</strong><p>Places you’re building together</p></div><div class="team-overview-card"><span class="stat-label">Pending invites</span><strong>${pending}</strong><p>Waiting for a response</p></div></div><div class="section-head"><h2>Your project circles</h2><a href="#/projects">Browse projects</a></div><div class="grid two">${projects.slice(0,4).map(p=>`<article class="card circle-card"><div class="circle-top"><div class="circle-mark">${p.title.slice(0,1)}</div><div><h3>${p.title}</h3><p>${p.category} · ${p.people.length} members</p></div><span class="circle-status">${p.status}</span></div><div class="circle-members">${teamMembers(p).slice(0,4).map(m=>avatar(m.initials,m.avatar||'blue')).join('')}<span>${Math.max(0,p.teamSize-teamMembers(p).length)} open spots</span></div><div class="circle-actions"><button class="button ghost small" onclick="location.hash='/teams/${p.id}'">Open team</button><button class="icon-btn" aria-label="Invite someone" onclick="location.hash='/discover'">+</button></div></article>`).join('')}</div><div class="section-head"><h2>People in your orbit</h2><a href="#/discover">See all contacts</a></div><div class="grid">${activePeople.slice(0,3).map(p=>`<article class="card contact-card" onclick="location.hash='/student/${people.indexOf(p)}'"><div class="contact-top">${avatar(p.initials,p.avatar)}<div><h3>${p.name}</h3><p>${p.role}</p></div><span class="online-dot"></span></div><div class="tags">${p.interests.slice(0,2).map(i=>`<span class="tag">${i}</span>`).join('')}</div><div class="contact-footer"><span>${p.score}% project fit</span><button class="text-button" onclick="event.stopPropagation();toast('Message composer ready for ${p.name.split(' ')[0]}')">Connect</button></div></article>`).join('')}</div></div>`,'/teams')}
function settingsPage(){const currentTheme=storage.read('theme','midnight');return shell(`<div class="page settings-page"><section class="hero"><div><div class="kicker">Workspace preferences</div><h1>Make it feel like yours.</h1><p>Choose how ProjectMatch looks, moves and keeps you in the loop.</p></div></section><div class="settings-layout"><aside class="settings-nav"><a class="active" href="#/settings">Appearance</a><a href="#/settings">Notifications</a><a href="#/settings">Profile visibility</a></aside><section class="settings-content"><div class="settings-section"><div><h2>Theme</h2><p>Pick the atmosphere you want for your workspace.</p></div><div class="theme-grid"><button class="theme-card ${currentTheme==='midnight'?'selected':''}" onclick="setTheme('midnight')"><span class="theme-preview midnight-preview"><i></i><i></i><i></i></span><strong>Midnight</strong><small>Deep charcoal & violet</small></button><button class="theme-card ${currentTheme==='pastel'?'selected':''}" onclick="setTheme('pastel')"><span class="theme-preview pastel-preview"><i></i><i></i><i></i></span><strong>Pastel Day</strong><small>Yellow, peach, pink & blue</small></button><button class="theme-card ${currentTheme==='burgundy'?'selected':''}" onclick="setTheme('burgundy')"><span class="theme-preview burgundy-preview"><i></i><i></i><i></i></span><strong>Burgundy</strong><small>Maroon, wine & rose</small></button></div></div><div class="settings-section settings-row"><div><h2>Motion</h2><p>Keep the small transitions that make the workspace feel alive.</p></div><label class="switch"><input id="motion-toggle" type="checkbox" checked onchange="toggleMotion(this.checked)" /><span></span></label></div><div class="settings-section settings-row"><div><h2>Profile visibility</h2><p>Let matching projects discover you when your skills fit.</p></div><label class="switch"><input type="checkbox" checked onchange="toast(this.checked?'You’re visible to matching projects':'Your profile is hidden')" /><span></span></label></div><div class="settings-section settings-row danger-row"><div><h2>Local data</h2><p>Your profile, projects and team requests are stored only in this browser.</p></div><button class="button ghost small" onclick="clearLocalData()">Reset local data</button></div></section></div></div>`,'/settings')}
function setTheme(theme){document.documentElement.dataset.theme=theme;storage.write('theme',theme);toast(`${theme[0].toUpperCase()+theme.slice(1)} theme applied`);render()}
function toggleMotion(enabled){document.documentElement.dataset.motion=enabled?'on':'off';storage.write('motion',enabled?'on':'off')}
function clearLocalData(){if(!confirm('Reset local ProjectMatch data?'))return;['profile','projects','teams','team-requests','theme','motion'].forEach(k=>localStorage.removeItem(`projectmatch:${k}`));toast('Local data reset');setTimeout(()=>location.reload(),400)}
function loginPage(){return `<div class="login-page"><div class="login-art" aria-hidden="true"><div class="art-grid"></div><div class="doodle doodle-star">✦</div><div class="doodle doodle-loop"></div><div class="doodle doodle-circle"></div><div class="doodle doodle-arrow">↗</div><div class="art-note note-one">good teams<br><span>start small.</span></div><div class="art-note note-two">skills × curiosity<br><span>= momentum</span></div><div class="art-line line-one"></div><div class="art-line line-two"></div><div class="login-art-copy"><span class="brand-mark"><svg viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3"><path d="m5 12 4.5 4.5L19 7"/></svg></span><span>ProjectMatch</span><h1>Find the people<br>who make ideas <em>move.</em></h1><p>A calmer way to discover projects, teammates and the next thing worth building.</p></div></div><main class="login-panel"><div class="login-card"><div class="login-card-top"><div><div class="kicker">Welcome back</div><h2>Sign in to your workspace</h2><p>Pick up where your best ideas left off.</p></div><button class="icon-btn" aria-label="Close login" onclick="location.hash='/'">×</button></div><button class="google-button" onclick="loginWithGoogle()"><span class="google-g">G</span><span>Continue with Google</span></button><div class="or-divider"><span>or continue with email</span></div><form onsubmit="handleLogin(event)"><label>Email address<input id="login-email" type="email" placeholder="you@university.edu" autocomplete="email" required></label><label>Password<div class="password-field"><input id="login-password" type="password" placeholder="At least 8 characters" minlength="8" autocomplete="current-password" required><button type="button" class="password-toggle" onclick="togglePassword()">Show</button></div></label><div class="login-options"><label class="check-label"><input type="checkbox"> <span>Remember me</span></label><button type="button" class="text-button" onclick="toast('Password recovery is ready for backend connection')">Forgot password?</button></div><button class="button primary login-submit" type="submit">Sign in ${icons.arrow}</button></form><p class="login-footer">New to ProjectMatch? <button class="text-button" onclick="location.hash='/onboarding'">Create your profile</button></p></div><p class="login-legal">By continuing, you agree to build thoughtfully.</p></main></div>`}
function loginWithGoogle(){storage.write('auth',{provider:'google',signedIn:true});toast('Signed in with Google');setTimeout(()=>location.hash='/',450)}
function handleLogin(e){e.preventDefault();const email=document.getElementById('login-email')?.value.trim(),password=document.getElementById('login-password')?.value||'';if(!email||password.length<8)return toast('Check your email and password','error');storage.write('auth',{provider:'email',email,signedIn:true});toast('Welcome back');setTimeout(()=>location.hash='/',450)}
function togglePassword(){const input=document.getElementById('login-password'),button=document.querySelector('.password-toggle');if(!input)return;input.type=input.type==='password'?'text':'password';if(button)button.textContent=input.type==='password'?'Show':'Hide'}
function avatar(i,c=''){return `<span class="avatar ${c}">${i}</span>`} function progressBar(v){return `<div class="progress"><span style="width:${v}%"></span></div>`} function skillRows(skills){return `<div class="skill-list">${skills.map(s=>`<div class="skill-row"><div><strong>${s.name}</strong><span>${s.level}%</span></div>${progressBar(s.level)}</div>`).join('')}</div>`} function toast(m,t='success'){const e=document.createElement('div');e.className=`toast ${t}`;e.innerHTML=`<span class="toast-icon">${t==='success'?icons.check:'!'}</span>${m}`;document.body.appendChild(e);requestAnimationFrame(()=>e.classList.add('show'));setTimeout(()=>{e.classList.remove('show');setTimeout(()=>e.remove(),250)},2800)}
function projectCard(p){const match=calculateCompatibility(user,p);return `<article class="card project-card clickable" onclick="location.hash='/project/${p.id}'"><div class="card-title"><div><div class="match-label">${match.score}% match</div><h3>${p.title}</h3></div><button class="icon-btn" aria-label="Save project" onclick="event.stopPropagation();toast('Saved to your projects')">♡</button></div><div class="project-category">${p.category} <span>·</span> ${p.status}</div><p>${p.desc}</p><div class="tags">${p.tags.slice(0,3).map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="bottom"><div class="people">${p.people.map((x,i)=>avatar(x,['mint','orange','blue'][i%3])).join('')}<span>${p.people.length+2} interested</span></div><span class="deadline">${p.deadline}</span></div></article>`}
function personCard(p){return `<article class="card profile-card clickable" onclick="location.hash='/student/${people.indexOf(p)}'"><div>${avatar(p.initials,p.avatar)}</div><div class="profile-copy"><h3>${p.name}</h3><div class="role">${p.role}</div><p>${p.bio}</p><div class="tags">${p.skills.map(s=>`<span class="tag">${s.name}</span>`).join('')}</div></div><div class="profile-score"><strong>${p.score}%</strong><span>match</span></div></article>`}
function shell(content,active='/'){const nav=navItems.map(([h,l,i])=>`<a href="#${h}" class="${active===h?'active':''}">${icons[i]}<span>${l}</span></a>`).join('');return `<div class="app-shell"><aside class="sidebar"><a class="brand" href="#/"><span class="brand-mark"><svg viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3"><path d="m5 12 4.5 4.5L19 7"/></svg></span>ProjectMatch</a><div class="eyebrow">Workspace</div><nav class="nav">${nav}</nav><div class="sidebar-spacer"></div><div class="eyebrow">Account</div><nav class="nav"><a href="#/profile" class="${active==='/profile'?'active':''}">${icons.user}<span>My profile</span></a><a href="#/settings" class="${active==='/settings'?'active':''}">${icons.settings}<span>Settings</span></a></nav><div class="mini-profile">${avatar(user.initials,'blue')}<div><strong>${user.name}</strong><span>Open to projects</span></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace <span class="faint">/</span> <strong>${active==='/'?'Overview':active.slice(1).replace('/',' · ')}</strong></div><div class="top-actions"><button class="icon-btn" aria-label="Notifications">${icons.bell}</button><button class="button primary small" onclick="location.hash='/projects'">Find a project</button></div></header>${content}</main><nav class="mobile-nav">${navItems.slice(0,4).map(([h,l,i])=>`<a href="#${h}" class="${active===h?'active':''}">${icons[i]}<span>${l}</span></a>`).join('')}</nav></div>`}
function overview(){return shell(`<div class="page"><section class="hero"><div><div class="kicker">Tuesday, October 8</div><h1>Good morning, ${user.name.split(' ')[0]}.</h1><p>Three new projects fit what you’re looking for. Here’s where your next great collaboration might start.</p></div><div class="hero-actions"><button class="button ghost" onclick="location.hash='/discover'">Browse people</button><button class="button primary" onclick="location.hash='/projects'">Explore projects</button></div></section><div class="stat-row"><div class="stat"><div class="stat-label">Profile strength</div><strong>82<span class="up">+8%</span></strong></div><div class="stat"><div class="stat-label">New matches</div><strong>12</strong></div><div class="stat"><div class="stat-label">Profile views</div><strong>48<span class="up">+14%</span></strong></div><div class="stat"><div class="stat-label">Saved projects</div><strong>07</strong></div></div><div class="section-head"><h2>Best matches for you</h2><a href="#/projects">View all projects</a></div><div class="grid">${projects.slice(0,3).map(projectCard).join('')}</div><div class="section-head"><h2>People you might click with</h2><a href="#/discover">See everyone</a></div><div class="grid two">${people.slice(0,2).map(personCard).join('')}</div></div>`,'/')}
function discover(){return shell(`<div class="page"><section class="hero"><div><div class="kicker">The network</div><h1>Find your people.</h1><p>Good teams are built from complementary instincts. Meet students whose skills and energy line up with yours.</p></div><button class="button primary" onclick="location.hash='/onboarding'">Complete your profile</button></section><div class="discovery-layout"><aside class="filter-panel"><div class="filter-heading"><strong>Refine matches</strong><button class="text-button" onclick="resetFilters()">Reset</button></div><label>Role<select id="role-filter" onchange="filterPeople()"><option value="all">Any role</option><option>Product designer</option><option>Full-stack builder</option><option>Data storyteller</option><option>Research + strategy</option></select></label><label>Skill<select id="skill-filter" onchange="filterPeople()"><option value="all">Any skill</option><option>React</option><option>Python</option><option>Figma</option><option>Research</option></select></label><label>Interest<select id="interest-filter" onchange="filterPeople()"><option value="all">Any interest</option><option>Education</option><option>Climate</option><option>Community</option><option>Wellbeing</option></select></label><label>Availability<select id="availability-filter" onchange="filterPeople()"><option value="all">Any availability</option><option>Flexible</option><option>Weekday evenings</option><option>Weekends</option><option>Mornings</option></select></label><div class="filter-note"><span class="spark">✦</span><div><strong>Smart matching</strong><p>Results are ordered by shared interests, skills and availability.</p></div></div></aside><section><div class="search-row"><div class="search">${icons.search}<input id="person-search" oninput="filterPeople()" placeholder="Search by name, skill or role" /></div><button class="filter" id="sort-filter" onclick="toggleSort()">Best match <span>⌄</span></button></div><div id="people-results" class="grid people-grid">${people.map(personCard).join('')}</div></section></div></div>`,'/discover')}
function filterPeople(){const q=(document.getElementById('person-search')?.value||'').toLowerCase(),role=document.getElementById('role-filter')?.value||'all',skill=document.getElementById('skill-filter')?.value||'all',interest=document.getElementById('interest-filter')?.value||'all',availability=document.getElementById('availability-filter')?.value||'all';let r=people.filter(p=>(!q||`${p.name} ${p.role} ${p.bio} ${p.skills.map(x=>x.name).join(' ')}`.toLowerCase().includes(q))&&(role==='all'||p.role===role)&&(skill==='all'||p.skills.some(x=>x.name===skill))&&(interest==='all'||p.interests.includes(interest))&&(availability==='all'||p.availability===availability));if(window.sortNewest)r=[...r].reverse();document.getElementById('people-results').innerHTML=r.length?r.map(personCard).join(''):`<div class="empty-state"><div class="empty-orb">⌕</div><h3>No close matches yet</h3><p>Try widening a filter or updating your profile so we can find a better fit.</p><button class="button ghost" onclick="resetFilters()">Clear filters</button></div>`}
function resetFilters(){['role-filter','skill-filter','interest-filter','availability-filter'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='all'});const i=document.getElementById('person-search');if(i)i.value='';window.sortNewest=false;filterPeople()} function toggleSort(){window.sortNewest=!window.sortNewest;const b=document.getElementById('sort-filter');if(b)b.innerHTML=window.sortNewest?'Recently active <span>⌄</span>':'Best match <span>⌄</span>';filterPeople()}
function projectsPage(){return shell(`<div class="page"><section class="hero"><div><div class="kicker">Open calls</div><h1>Projects worth joining.</h1><p>Browse ideas with enough shape to get started—and enough room for you to make them better.</p></div><button class="button primary" onclick="location.hash='/create-project'">+ Start a project</button></section><div class="project-toolbar"><div class="search">${icons.search}<input id="project-search" oninput="filterProjects()" placeholder="Search projects" /></div><div class="filter-row"><select class="filter" id="project-category" onchange="filterProjects()"><option value="all">All categories</option><option>Education</option><option>Climate</option><option>Community</option><option>Wellbeing</option><option>Civic tech</option><option>Sustainability</option></select><select class="filter" id="project-skill" onchange="filterProjects()"><option value="all">All skills</option><option>React</option><option>Python</option><option>Research</option><option>Data viz</option><option>Frontend</option></select><select class="filter" id="project-size" onchange="filterProjects()"><option value="all">Any team size</option><option value="4">Up to 4</option><option value="5">Up to 5</option><option value="6">Up to 6</option></select></div></div><div id="project-results" class="grid">${projects.length?projects.map(projectCard).join(''):`<div class="empty-state"><div class="empty-orb">✦</div><h3>No projects yet</h3><p>Create the first project and start building your team.</p><button class="button primary" onclick="location.hash='/create-project'">Create a project</button></div>`}</div></div>`,'/projects')}
function filterProjects(){const q=(document.getElementById('project-search')?.value||'').toLowerCase(),cat=document.getElementById('project-category')?.value||'all',skill=document.getElementById('project-skill')?.value||'all',size=document.getElementById('project-size')?.value||'all';const r=projects.filter(p=>(!q||`${p.title} ${p.desc} ${p.category} ${p.tags.join(' ')}`.toLowerCase().includes(q))&&(cat==='all'||p.category===cat)&&(skill==='all'||p.tags.includes(skill))&&(size==='all'||p.teamSize<=Number(size)));document.getElementById('project-results').innerHTML=r.length?r.map(projectCard).join(''):`<div class="empty-state"><div class="empty-orb">⌕</div><h3>No projects found</h3><p>Try another search or clear your filters to see more open calls.</p><button class="button ghost" onclick="resetProjectFilters()">Clear filters</button></div>`}
function resetProjectFilters(){['project-category','project-skill','project-size'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='all'});const i=document.getElementById('project-search');if(i)i.value='';filterProjects()}
function profile(){return shell(`<div class="page"><section class="profile-hero">${avatar(user.initials,'blue')}<div><div class="kicker">Your profile</div><h1>${user.name}</h1><p>${user.role} · Curious generalist · ${user.availability}</p></div><div class="profile-actions"><button class="button ghost" onclick="toast('Profile preview copied')">Preview</button><button class="button primary" onclick="location.hash='/onboarding'">Edit profile</button></div></section><div class="profile-grid"><section><div class="section-head"><h2>About you</h2></div><div class="card profile-about"><div class="card-title"><h3>Your story</h3><span class="tag accent">82% complete</span></div><p>${user.bio}</p><div class="profile-meta"><div><span class="faint">Availability</span><strong>${user.availability}</strong></div><div><span class="faint">Preferred roles</span><strong>Frontend · Product</strong></div></div></div><div class="section-head"><h2>Skills & proficiency</h2></div><div class="card">${skillRows(user.skills)}</div><div class="section-head"><h2>Previous projects</h2></div><div class="card experience-card"><div class="experience-icon">✦</div><div><h3>Campus events app</h3><p>${user.experience}</p></div></div></section><aside><div class="section-head"><h2>Interests</h2></div><div class="card interest-card"><div class="tags">${user.interests.map(t=>`<span class="tag accent">${t}</span>`).join('')}</div><div class="interest-note">Your interests help us find people you’ll enjoy working with.</div></div><div class="section-head"><h2>Profile health</h2></div><div class="card health-card"><div class="health-ring">82<span>%</span></div><div><h3>Strong foundation</h3><p>Add one more project to unlock better matches.</p></div></div></aside></div></div>`,'/profile')}
function studentDetail(i){const p=people[i]||people[0];return shell(`<div class="page"><button class="back-link" onclick="history.back()">← Back to discover</button><section class="detail-hero"><div class="detail-person">${avatar(p.initials,p.avatar)}<div><div class="kicker">${p.score}% compatibility</div><h1>${p.name}</h1><p>${p.role} · ${p.availability}</p></div></div><button class="button primary" onclick="toast('Invite sent to ${p.name.split(' ')[0]}')">Invite to project</button></section><div class="detail-grid"><section><div class="section-head"><h2>About ${p.name.split(' ')[0]}</h2></div><div class="card"><p class="detail-bio">${p.bio}</p><div class="shared-box"><span class="spark">✦</span><div><strong>You have ${p.shared.length} shared interests</strong><p>${p.shared.join(' · ')}</p></div></div></div><div class="section-head"><h2>Skills</h2></div><div class="card">${skillRows(p.skills)}</div><div class="section-head"><h2>Projects</h2></div><div class="detail-projects">${p.projects.map(n=>`<div class="card mini-project"><span class="project-dot"></span><div><h3>${n}</h3><p>Previous collaboration</p></div>${icons.arrow}</div>`).join('')}</div></section><aside><div class="section-head"><h2>Why this match</h2></div><div class="card match-explainer"><div class="score large">${p.score}%</div><div class="reasons"><div class="reason"><i>✓</i> Complementary ${p.skills[0].name} strength</div><div class="reason"><i>✓</i> Shared interest in ${p.shared[0]}</div><div class="reason"><i>✓</i> Availability can overlap</div><div class="reason warn"><i>△</i> Different working rhythms</div></div></div><div class="section-head"><h2>Interests</h2></div><div class="card"><div class="tags">${p.interests.map(t=>`<span class="tag ${p.shared.includes(t)?'accent':''}">${t}</span>`).join('')}</div></div></aside></div></div>`,'/discover')}
const onboardingSteps=[{eyebrow:'Let’s start simple',title:'What should we call you?',copy:'This is how your future teammates will see you.',fields:`<label>First and last name<input id="on-name" value="${user.name}" placeholder="Jordan Davis" /></label><label>What do you do best?<input id="on-role" value="${user.role}" placeholder="Product designer, frontend builder…" /></label>`},{eyebrow:'Make it yours',title:'Give people a reason to say hello.',copy:'A few honest lines are more useful than a perfect bio.',fields:`<div class="avatar-upload">${avatar(user.initials,'blue')}<button class="button ghost small" type="button" onclick="toast('Avatar upload is ready for backend connection')">Change avatar</button></div><label>Short bio<textarea id="on-bio" rows="4" placeholder="What are you curious about?">${user.bio}</textarea></label>`},{eyebrow:'Your edge',title:'What can you bring to a team?',copy:'Choose your strongest skills, then give us a rough confidence level.',fields:`<div class="skill-picker">${['React','JavaScript','Figma','Python','Research','Data viz','Writing','Prototyping'].map((s,i)=>`<button type="button" class="skill-choice ${user.skills.some(x=>x.name===s)?'selected':''}" onclick="this.classList.toggle('selected')">${s}<span>${user.skills.find(x=>x.name===s)?.level||[90,84,72,60,70,65,68,68][i]}%</span></button>`).join('')}</div><p class="form-hint">Pick at least two skills. You can fine-tune proficiency later.</p>`},{eyebrow:'Find your people',title:'What kind of work pulls you in?',copy:'Shared interests make the best first conversation.',fields:`<div class="skill-picker interests">${['Product','Education','Climate','Wellbeing','Civic tech','Community','Research','Creative tools'].map(s=>`<button type="button" class="skill-choice ${user.interests.includes(s)?'selected':''}" onclick="this.classList.toggle('selected')">${s}</button>`).join('')}</div><label>When are you usually available?<select id="on-availability"><option>Evenings + weekends</option><option>Weekday evenings</option><option>Weekends</option><option>Flexible</option><option>Mornings</option></select></label>`},{eyebrow:'One last thing',title:'Show the work behind the work.',copy:'Past projects help us understand what kinds of teams might fit.',fields:`<label>Previous project experience<textarea id="on-experience" rows="5">${user.experience}</textarea></label><div class="onboarding-note"><span class="spark">✦</span><span>You’re in control. You can edit or hide anything from your profile later.</span></div>`}];
let onboardingStep=0;function onboarding(){const s=onboardingSteps[onboardingStep];return `<div class="onboarding-shell"><div class="onboarding-top"><a class="brand" href="#/"><span class="brand-mark"><svg viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3"><path d="m5 12 4.5 4.5L19 7"/></svg></span>ProjectMatch</a><button class="text-button" onclick="location.hash='/profile'">Save & exit</button></div><main class="onboarding-main"><div class="onboarding-progress"><span>Profile setup</span><strong>${onboardingStep+1} / ${onboardingSteps.length}</strong><div><i style="width:${((onboardingStep+1)/onboardingSteps.length)*100}%"></i></div></div><section class="onboarding-card"><div class="kicker">${s.eyebrow}</div><h1>${s.title}</h1><p>${s.copy}</p><form onsubmit="nextOnboarding(event)">${s.fields}<div class="onboarding-actions">${onboardingStep?'<button class="button ghost" type="button" onclick="prevOnboarding()">Back</button>':'<span></span>'}<button class="button primary" type="submit">${onboardingStep===onboardingSteps.length-1?'Finish profile':'Continue'} ${icons.arrow}</button></div></form></section></main></div>`}
function nextOnboarding(e){e.preventDefault();if(onboardingStep===0&&!document.getElementById('on-name')?.value.trim())return toast('Add your name to continue','error');if(onboardingStep<onboardingSteps.length-1){if(onboardingStep===0){user.name=document.getElementById('on-name').value;user.initials=user.name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();user.role=document.getElementById('on-role').value||user.role}if(onboardingStep===1)user.bio=document.getElementById('on-bio').value;onboardingStep++;render()}else{user.experience=document.getElementById('on-experience').value;user.availability=document.getElementById('on-availability')?.value||user.availability;const selected=[...document.querySelectorAll('.skill-choice.selected')].map(x=>x.firstChild.textContent.trim());user.interests=selected.filter(x=>['Product','Education','Climate','Wellbeing','Civic tech','Community','Research','Creative tools'].includes(x));storage.write('profile',user);toast('Your profile is ready');location.hash='/profile'}}function prevOnboarding(){if(onboardingStep>0){onboardingStep--;render()}}
const projectSteps=[{eyebrow:'Start with the spark',title:'What are you building?',copy:'Give your idea a clear name people can remember.',fields:`<label>Project name<input id="pr-name" placeholder="Smart Campus Navigation" /></label><label>One-line description<textarea id="pr-desc" rows="3" placeholder="What will this make easier, better or more possible?"></textarea></label>`},{eyebrow:'Shape the work',title:'What kind of project is this?',copy:'This helps the right people find you.',fields:`<label>Category<select id="pr-category"><option>Education</option><option>Climate</option><option>Community</option><option>Wellbeing</option><option>Civic tech</option><option>Sustainability</option><option>Creative tools</option></select></label><div class="field-heading">Required skills <span>Choose up to five</span></div><div class="skill-picker">${['React','Python','Product design','Research','Data viz','Frontend','Writing','Maps'].map((s,i)=>`<button type="button" class="skill-choice" onclick="this.classList.toggle('selected')">${s}<span>${['Essential','Important','Nice to have'][i%3]}</span></button>`).join('')}</div>`},{eyebrow:'Set expectations',title:'Who would make this sing?',copy:'Specific asks make it easier for the right teammate to say yes.',fields:`<label>Team size<select id="pr-size"><option value="3">3 people</option><option value="4">4 people</option><option value="5">5 people</option><option value="6">6 people</option></select></label><label>Preferred interests<input id="pr-interest" placeholder="Education, climate, community…" /></label><label>Deadline<input id="pr-deadline" placeholder="e.g. End of November" /></label><label>Project status<select id="pr-status"><option>Recruiting</option><option>Early idea</option><option>In progress</option></select></label>`}];
let projectStep=0;
function createProject(){const s=projectSteps[projectStep];return `<div class="onboarding-shell"><div class="onboarding-top"><a class="brand" href="#/"><span class="brand-mark"><svg viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3"><path d="m5 12 4.5 4.5L19 7"/></svg></span>ProjectMatch</a><button class="text-button" onclick="location.hash='/projects'">Save & exit</button></div><main class="onboarding-main project-form"><div class="onboarding-progress"><span>Project setup</span><strong>${projectStep+1} / ${projectSteps.length}</strong><div><i style="width:${((projectStep+1)/projectSteps.length)*100}%"></i></div></div><section class="onboarding-card"><div class="kicker">${s.eyebrow}</div><h1>${s.title}</h1><p>${s.copy}</p><form onsubmit="nextProject(event)">${s.fields}<div class="onboarding-actions">${projectStep?'<button class="button ghost" type="button" onclick="prevProject()">Back</button>':'<span></span>'}<button class="button primary" type="submit">${projectStep===projectSteps.length-1?'Publish project':'Continue'} ${icons.arrow}</button></div></form></section></main></div>`}
function nextProject(e){e.preventDefault();if(projectStep===0&&(!document.getElementById('pr-name')?.value.trim()||!document.getElementById('pr-desc')?.value.trim()))return toast('Add a name and description to continue','error');if(projectStep<projectSteps.length-1){projectStep++;render()}else{const selected=[...document.querySelectorAll('.skill-choice.selected')].map(x=>x.firstChild.textContent.trim());if(selected.length<2)return toast('Choose at least two required skills','error');const id=`project-${Date.now()}`;const p={id,title:document.getElementById('pr-name').value,desc:document.getElementById('pr-desc').value,category:document.getElementById('pr-category').value,tags:selected,interest:document.getElementById('pr-interest').value||'Open to all interests',people:[user.initials],deadline:document.getElementById('pr-deadline').value||'Date to be announced',score:98,status:document.getElementById('pr-status').value,teamSize:Number(document.getElementById('pr-size').value),owner:user.name,ownerInitials:user.initials,roles:selected.slice(0,2)};projects=[p,...projects];storage.write('projects',projects);projectStep=0;toast('Project published');location.hash=`/project/${id}`}}
function prevProject(){if(projectStep>0){projectStep--;render()}}
function projectDetail(id){const p=projects.find(x=>x.id===id)||projects[0];return shell(`<div class="page"><button class="back-link" onclick="location.hash='/projects'">← Back to projects</button><section class="project-detail-hero"><div><div class="kicker">${p.score}% match · ${p.status}</div><h1>${p.title}</h1><p>${p.category} · looking for ${Math.max(0,p.teamSize-(p.people?.length||1))} more people</p></div><div class="detail-actions"><button class="button ghost" onclick="toast('Project link copied')">Share</button><button class="button primary" onclick="toast('You joined ${p.title}')">Join project</button></div></section><div class="project-detail-grid"><section><div class="section-head"><h2>The idea</h2></div><div class="card"><p class="detail-bio">${p.desc}</p><p class="detail-bio">We’re looking for thoughtful collaborators who want to make the first version real, learn quickly and leave the project better than they found it.</p></div><div class="section-head"><h2>What we need</h2></div><div class="card skill-importance">${p.tags.map((t,i)=>`<div><span class="tag ${i===0?'accent':''}">${t}</span><span class="importance ${i===0?'essential':i===1?'important':''}">${i===0?'Essential':i===1?'Important':'Nice to have'}</span></div>`).join('')}</div><div class="section-head"><h2>Current team</h2></div><div class="team-row">${p.people.map((x,i)=>`<div class="card team-person">${avatar(x,['mint','orange','blue'][i%3])}<div><strong>${i===0?p.owner:'Team member'}</strong><span>${i===0?'Project owner':'Contributor'}</span></div></div>`).join('')}</div></section><aside><div class="section-head"><h2>Project snapshot</h2></div><div class="card snapshot"><div><span>Team size</span><strong>${p.people?.length||1} / ${p.teamSize}</strong></div><div><span>Deadline</span><strong>${p.deadline}</strong></div><div><span>Category</span><strong>${p.category}</strong></div></div><div class="section-head"><h2>Why this matches</h2></div><div class="card match-explainer"><div class="score large">${p.score}%</div><div class="reasons"><div class="reason"><i>✓</i> Strong ${p.tags[0]} compatibility</div><div class="reason"><i>✓</i> Relevant ${p.interest} interests</div><div class="reason"><i>✓</i> Your availability overlaps</div><div class="reason warn"><i>△</i> Experience can grow here</div></div></div>${p.owner===user.name?`<div class="owner-tools"><button class="button ghost small" onclick="editProject('${p.id}')">Edit project</button><button class="text-button danger" onclick="deleteProject('${p.id}')">Delete</button></div>`:''}</aside></div></div>`,'/projects')}
function projectDetailV2(id){const p=projects.find(x=>x.id===id)||projects[0];if(!p)return `<div class="empty-state"><h3>Project not found</h3><button class="button primary" onclick="location.hash='/projects'">Back to projects</button></div>`;const match=calculateCompatibility(user,p),teamPeople=p.people.map(x=>people.find(person=>person.initials===x)).filter(Boolean),gaps=identifyTeamGaps(p,teamPeople),ranked=rankStudentsForProject(p,p.people||[]).slice(0,3);return shell(`<div class="page"><button class="back-link" onclick="location.hash='/projects'">← Back to projects</button><section class="project-detail-hero"><div><div class="kicker">${match.score}% match · ${p.status}</div><h1>${p.title}</h1><p>${p.category} · looking for ${Math.max(0,p.teamSize-(p.people?.length||1))} more people</p></div><div class="detail-actions"><button class="button ghost" onclick="toast('Project link copied')">Share</button><button class="button ghost" onclick="location.hash='/teams/${p.id}'">Find teammates</button><button class="button primary" onclick="toast('You joined ${p.title}')">Join project</button></div></section><div class="project-detail-grid"><section><div class="section-head"><h2>The idea</h2></div><div class="card"><p class="detail-bio">${p.desc}</p><p class="detail-bio">We’re looking for thoughtful collaborators who want to make the first version real, learn quickly and leave the project better than they found it.</p></div><div class="section-head"><h2>What we need</h2></div><div class="card skill-importance">${p.tags.map((t,i)=>`<div><span class="tag ${i===0?'accent':''}">${t}</span><span class="importance ${i===0?'essential':i===1?'important':''}">${i===0?'Essential':i===1?'Important':'Nice to have'}</span></div>`).join('')}</div><div class="section-head"><h2>Current team</h2></div><div class="team-row">${p.people.map((x,i)=>`<div class="card team-person">${avatar(x,['mint','orange','blue'][i%3])}<div><strong>${teamPeople[i]?.name||'Team member'}</strong><span>${i===0?'Project owner':'Contributor'}</span></div></div>`).join('')}</div>${gaps.hasGap?`<div class="team-gap"><div class="gap-icon">!</div><div><strong>Team gap detected</strong><p>Missing ${gaps.missing.join(' · ')}</p></div></div>`:''}<div class="section-head"><h2>Recommended teammates</h2><a href="#/discover">See all</a></div><div class="recommended-list">${ranked.length?ranked.map(person=>`<article class="card recommended"><div>${avatar(person.initials,person.avatar)}</div><div class="recommended-copy"><h3>${person.name}</h3><p>${person.role} · ${person.match.score}% compatible</p><div class="reason-line">✓ ${person.match.reasons[0]?.text||'Strong overall fit'}</div></div><button class="button ghost small" onclick="toast('Invite sent to ${person.name.split(' ')[0]}')">Invite</button></article>`).join(''):`<div class="empty-state"><h3>No recommendations yet</h3><p>More student profiles will appear here as the network grows.</p></div>`}</div></section><aside><div class="section-head"><h2>Compatibility panel</h2></div><div class="card compatibility-panel"><div class="compat-score"><div class="score large">${match.score}%</div><div><strong>Strong fit</strong><p>Based on five transparent signals</p></div></div>${[['Skills',match.breakdown.skills,50],['Interests',match.breakdown.interests,20],['Role',match.breakdown.role,10],['Availability',match.breakdown.availability,10],['Experience',match.breakdown.experience,10]].map(x=>`<div class="breakdown-row"><div><span>${x[0]}</span><strong>${x[1]}%</strong></div><div class="progress"><span style="width:${x[1]}%"></span></div><small>${x[2]}% of score</small></div>`).join('')}<div class="reasons match-reasons">${match.reasons.map(r=>`<div class="reason ${r.type==='warn'?'warn':''}"><i>${r.type==='warn'?'△':'✓'}</i>${r.text}</div>`).join('')}</div></div><div class="section-head"><h2>Project snapshot</h2></div><div class="card snapshot"><div><span>Team size</span><strong>${p.people?.length||1} / ${p.teamSize}</strong></div><div><span>Deadline</span><strong>${p.deadline}</strong></div><div><span>Category</span><strong>${p.category}</strong></div></div>${p.owner===user.name?`<div class="owner-tools"><button class="button ghost small" onclick="editProject('${p.id}')">Edit project</button><button class="text-button danger" onclick="deleteProject('${p.id}')">Delete</button></div>`:''}</aside></div></div>`,'/projects')}
function teamBuilder(id){const p=projects.find(x=>x.id===id)||projects[0];if(!p)return `<div class="empty-state"><h3>Create a project before building a team</h3><button class="button primary" onclick="location.hash='/create-project'">Create project</button></div>`;const members=teamMembers(p),health=teamHealth(p,members),gaps=identifyTeamGaps(p,members),candidates=rankTeamCandidates(p,members).slice(0,4),requests=teamRequests.filter(r=>r.projectId===p.id);return shell(`<div class="page team-builder-page"><button class="back-link" onclick="location.hash='/project/${p.id}'">← Back to ${p.title}</button><section class="hero team-builder-hero"><div><div class="kicker">Team builder</div><h1>Shape the team.</h1><p>Bring together the right mix of skills, working styles and curiosity for <strong>${p.title}</strong>.</p></div><div class="health-summary"><div class="health-ring">${health.overall}<span>%</span></div><div><span>Overall team health</span><strong>${health.overall>=80?'Strong foundation':health.overall>=60?'Promising mix':'Needs coverage'}</strong></div></div></section><div class="builder-layout"><section class="builder-column requirements-column"><div class="column-kicker">01 / Requirements</div><h2>What this project needs</h2><p class="column-copy">Fill the essential roles first. The rest can grow with the team.</p><div class="requirement-list">${(p.roles?.length?p.roles:p.tags).map((role,i)=>{const filled=members.some(m=>skillMatches(role,m.role)||(m.skills||[]).some(s=>skillMatches(role,s.name)));return `<div class="requirement-row ${filled?'filled':''}"><span class="requirement-status">${filled?'✓':'!'}</span><div><strong>${role}</strong><small>${i===0?'Essential':i===1?'Important':'Nice to have'}</small></div><span class="requirement-label">${filled?'Filled':'Missing'}</span></div>`}).join('')}</div><div class="team-health-card"><div class="column-kicker">Team health</div>${[['Skill coverage',health.skill],['Role coverage',health.role],['Interest alignment',health.interest]].map(x=>`<div class="health-meter"><div><span>${x[0]}</span><strong>${x[1]}%</strong></div>${progressBar(x[1])}</div>`).join('')}</div></section><section class="builder-column current-column"><div class="column-kicker">02 / Current team <span>${members.length} of ${p.teamSize}</span></div><h2>Your team</h2><p class="column-copy">A balanced team beats a crowded one.</p><div class="current-team-list">${members.length?members.map(m=>{const pm=calculateCompatibility(m,p);return `<article class="card current-member">${avatar(m.initials,m.avatar||'blue')}<div class="member-main"><div class="member-name"><h3>${m.name}</h3><span>${pm.score}% match</span></div><p>${m.role}</p><div class="tags">${(m.skills||[]).slice(0,2).map(s=>`<span class="tag">${s.name}</span>`).join('')}</div></div><button class="icon-btn remove-member" aria-label="Remove ${m.name}" onclick="removeTeamMember('${p.id}','${m.initials}')">×</button></article>`}).join(''):`<div class="empty-state compact"><div class="empty-orb">+</div><h3>No teammates selected</h3><p>Add a recommended teammate to start shaping the team.</p></div>`}</div><div class="overall-team-score"><div><span>Overall team compatibility</span><strong>${health.overall}%</strong></div><div class="progress"><span style="width:${health.overall}%"></span></div></div>${requests.length?`<div class="requests-card"><div class="column-kicker">Team requests</div>${requests.map(r=>`<div class="request-row"><div>${avatar(r.initials,r.avatar)}<div><strong>${r.name}</strong><span>${r.status}</span></div></div><div class="request-actions"><button class="text-button" onclick="setRequestStatus('${r.id}','Accepted')">Accept</button><button class="text-button danger" onclick="setRequestStatus('${r.id}','Declined')">Decline</button></div></div>`).join('')}</div>`:''}</section><section class="builder-column recommendations-column"><div class="column-kicker">03 / Recommendations</div><h2>Best next teammate</h2><p class="column-copy">Ranked by project fit, missing-skill coverage and team diversity.</p>${gaps.hasGap?`<div class="gap-inline"><span>!</span><div><strong>Missing ${gaps.missing[0]}</strong><p>These candidates help close the gap.</p></div></div>`:''}<div class="candidate-list">${candidates.length?candidates.map(c=>`<article class="card candidate-card"><div class="candidate-top">${avatar(c.initials,c.avatar)}<div><h3>${c.name}</h3><p>${c.role}</p></div><div class="candidate-score"><strong>${c.match.score}%</strong><span>match</span></div></div><div class="candidate-fit">${c.fills?`Best candidate for missing ${gaps.missing[0]||'role'}`:'Strong overall fit'}</div><div class="reason-line">✓ ${c.match.reasons[0]?.text||'Good complementary skills'}</div><div class="candidate-actions"><button class="button ghost small" onclick="location.hash='/student/${people.indexOf(c)}'">View profile</button><button class="button primary small" onclick="inviteTeamMember('${p.id}','${c.initials}')">Invite</button></div></article>`).join(''):`<div class="empty-state compact"><div class="empty-orb">⌕</div><h3>No candidates available</h3><p>Everyone in the current network is already on this team.</p></div>`}</div></section></div></div>`,'/teams')}
function addTeamMember(projectId,initials){const p=projects.find(x=>x.id===projectId),member=people.find(x=>x.initials===initials)|| (initials===user.initials?user:null);if(!p||!member)return;const members=teamMembers(p);if(members.length>=p.teamSize)return toast('This team is full','error');if(members.some(x=>x.initials===initials))return toast('Already on this team','error');saveTeam(p,[...members,member]);toast(`${member.name} added to the team`);render()}
function removeTeamMember(projectId,initials){const p=projects.find(x=>x.id===projectId);if(!p)return;const members=teamMembers(p).filter(x=>x.initials!==initials);saveTeam(p,members);toast('Member removed');render()}
function replaceTeamMember(projectId,initials){const p=projects.find(x=>x.id===projectId);if(!p)return;const members=teamMembers(p).filter(x=>x.initials!==initials),candidate=rankTeamCandidates(p,members)[0];if(!candidate)return toast('No replacement available','error');saveTeam(p,[...members,candidate]);toast(`${candidate.name} is now on the team`);render()}
function inviteTeamMember(projectId,initials){const p=projects.find(x=>x.id===projectId),member=people.find(x=>x.initials===initials);if(!p||!member)return;const existing=teamRequests.find(r=>r.projectId===projectId&&r.initials===initials);if(existing)return toast('Invite already pending','error');teamRequests=[...teamRequests,{id:`request-${Date.now()}`,projectId,initials,name:member.name,avatar:member.avatar,status:'Pending'}];storage.write('team-requests',teamRequests);toast(`Invite sent to ${member.name.split(' ')[0]}`);render()}
function setRequestStatus(id,status){const request=teamRequests.find(r=>r.id===id);teamRequests=teamRequests.map(r=>r.id===id?{...r,status}:r);storage.write('team-requests',teamRequests);if(status==='Accepted'&&request)addTeamMember(request.projectId,request.initials);else{toast(`Request ${status.toLowerCase()}`);render()}}
function editProject(id){const p=projects.find(x=>x.id===id);if(!p)return;const title=prompt('Project name',p.title);if(title===null)return;const desc=prompt('Description',p.desc);if(desc===null)return;p.title=title.trim()||p.title;p.desc=desc.trim()||p.desc;storage.write('projects',projects);toast('Project updated');render()}
function deleteProject(id){if(!confirm('Delete this project?'))return;projects=projects.filter(p=>p.id!==id);storage.write('projects',projects);toast('Project deleted');location.hash='/projects'}
function render(){const path=location.hash.slice(1)||'/';if(path==='/login'){document.getElementById('app').innerHTML=loginPage();return}if(path==='/onboarding'){document.getElementById('app').innerHTML=onboarding();return}if(path==='/create-project'){document.getElementById('app').innerHTML=createProject();return}const sm=path.match(/^\/student\/(\d+)/),pm=path.match(/^\/project\/(.+)/),tm=path.match(/^\/teams(?:\/(.+))?/);document.getElementById('app').innerHTML=sm?studentDetail(Number(sm[1])):pm?projectDetailV2(pm[1]):tm?(tm[1]?teamBuilder(tm[1]):teamsPage()):path==='/discover'?discover():path==='/projects'?projectsPage():path==='/profile'?profile():path==='/settings'?settingsPage():overview();window.scrollTo(0,0)}window.addEventListener('hashchange',render);render();
